import { expect, it } from 'vitest';
import data from './examples.json';
import { recordedSamples, serializeExamplesFile } from './templates';

// examples.json is generated by record mode when it saves templates.json. If templates.json was
// edited some other way, re-save from record mode (?record=1) to regenerate it.
it('examples.json is up to date with templates.json', () => {
  expect(data).toEqual(JSON.parse(serializeExamplesFile(recordedSamples)));
});
